import{_ as t,o as e,c as i,a4 as o}from"./chunks/framework.BAxM5-cj.js";const d=JSON.parse('{"title":"PROJECT CONTEXT: BRANDHUB (BH)","description":"","frontmatter":{},"headers":[],"relativePath":"Report_DA-E08/project_context.md","filePath":"Report_DA-E08/project_context.md"}'),r={name:"Report_DA-E08/project_context.md"};function a(h,n,g,c,l,s){return e(),i("div",null,[...n[0]||(n[0]=[o('<h1 id="project-context-brandhub-bh" tabindex="-1">PROJECT CONTEXT: BRANDHUB (BH) <a class="header-anchor" href="#project-context-brandhub-bh" aria-label="Permalink to &quot;PROJECT CONTEXT: BRANDHUB (BH)&quot;">​</a></h1><h2 id="_1-tong-quan-du-an-project-overview" tabindex="-1">1. Tổng quan dự án (Project Overview) <a class="header-anchor" href="#_1-tong-quan-du-an-project-overview" aria-label="Permalink to &quot;1. Tổng quan dự án (Project Overview)&quot;">​</a></h2><ul><li><strong>Tên dự án:</strong> BrandHub (Tên viết tắt: BH)</li><li><strong>Định nghĩa:</strong> Nền tảng sản xuất và phân phối nội dung đa kênh ứng dụng trí tuệ nhân tạo (AI-Powered) dành cho các công ty truyền thông (Marketing Agencies).</li><li><strong>Mục tiêu cốt lõi:</strong><ul><li>Tự động hóa quy trình tạo nội dung (caption, hình ảnh, video ngắn) từ text input.</li><li>Đảm bảo tính chính xác và nhất quán thương hiệu bằng hệ thống RAG (Retrieval-Augmented Generation) kết hợp Vector Database.</li><li>Quản lý tập trung nhiều khách hàng (Brand Clients) trên cùng một nền tảng, chia theo không gian làm việc (Workspaces).</li><li>Cung cấp Client Portal để khách hàng duyệt, theo dõi và phê duyệt bài viết.</li><li>Quét (crawl) xu hướng thời gian thực từ Google Trends, TikTok, Facebook để gợi ý ý tưởng.</li><li>Lên lịch và tự động đăng bài an toàn qua các kênh: Facebook, Instagram, TikTok, Threads, Zalo OA bằng hệ thống Message Queue.</li></ul></li></ul><h2 id="_2-kien-truc-cong-nghe-tech-stack" tabindex="-1">2. Kiến trúc &amp; Công nghệ (Tech Stack) <a class="header-anchor" href="#_2-kien-truc-cong-nghe-tech-stack" aria-label="Permalink to &quot;2. Kiến trúc &amp; Công nghệ (Tech Stack)&quot;">​</a></h2><ul><li><strong>Kiến trúc:</strong> Microservices (Gồm Business Service, Publisher Service và AI Service giao tiếp qua Spring Cloud Gateway).</li><li><strong>Front-end:</strong> React + Vite, Tailwind CSS (Web Dashboard); React Native (Android App).</li><li><strong>Back-end:</strong> Java Spring Boot, Python FastAPI (AI Service).</li><li><strong>Database:</strong> MongoDB (Query &lt; 200ms trên indexed fields), PostgreSQL, Redis, VectorDB (lưu tài liệu thương hiệu).</li><li><strong>Message Queue:</strong> RabbitMQ (Đảm bảo thứ tự FIFO, cơ chế Acknowledgement, tự động retry 3 lần khi lỗi).</li><li><strong>Lưu trữ &amp; Hạ tầng:</strong> AWS S3 (Lưu media, truy cập qua presigned URL), Docker &amp; Docker Compose, GitHub Actions (CI/CD).</li></ul><h2 id="_3-phan-quyen-luong-van-hanh-user-roles-workflows" tabindex="-1">3. Phân quyền &amp; Luồng vận hành (User Roles &amp; Workflows) <a class="header-anchor" href="#_3-phan-quyen-luong-van-hanh-user-roles-workflows" aria-label="Permalink to &quot;3. Phân quyền &amp; Luồng vận hành (User Roles &amp; Workflows)&quot;">​</a></h2><p>Hệ thống áp dụng mãnh liệt cơ chế bảo mật RBAC và cô lập dữ liệu hoàn toàn giữa các không gian làm việc (cross-workspace isolation). Có 6 vai trò chính:</p><ul><li><strong>Admin:</strong> Quản trị toàn hệ thống, cấu hình gói subscription (Free, Basic, Pro, Enterprise), quản lý người dùng, xem báo cáo doanh thu/sử dụng AI.</li><li><strong>Agency Owner:</strong> Tạo và cấu hình Workspace cho agency; Onboard client (tạo profile riêng); Mời và phân quyền cho Account Manager (AM) và Content Creator; Theo dõi hiệu suất tổng thể.</li><li><strong>Account Manager (AM):</strong> Tiếp nhận content request từ Client -&gt; Giao việc cho Creator -&gt; Duyệt bài do Creator nộp -&gt; Chuyển bài cho Client duyệt -&gt; Đặt lịch lên nội dung trên Calendar sau khi được duyệt hoàn toàn -&gt; Kết nối tài khoản mạng xã hội của client.</li><li><strong>Content Creator:</strong> Nhận brief -&gt; Dùng AI sinh caption/hài hòa theo brand guidelines (RAG) -&gt; Dùng AI sinh ảnh/video -&gt; Tối ưu hóa độ dài/định dạng theo từng platform -&gt; Preview hiển thị realtime -&gt; Gửi AM duyệt.</li><li><strong>Brand Client:</strong> Đăng nhập Client Portal riêng biệt -&gt; Gửi Content Request -&gt; Theo dõi tiến độ task -&gt; Xem preview, Duyệt/Từ chối bài viết kèm feedback -&gt; Xem lịch đăng bài (Read-only Calendar) và lịch sử bài đã đăng.</li><li><strong>Guest:</strong> Xem Landing page, đăng ký/đăng nhập (hỗ trợ Google OAuth).</li></ul><h2 id="_4-cac-rang-buoc-phi-chuc-nang-quan-trong-key-non-functional-requirements" tabindex="-1">4. Các ràng buộc phi chức năng quan trọng (Key Non-Functional Requirements) <a class="header-anchor" href="#_4-cac-rang-buoc-phi-chuc-nang-quan-trong-key-non-functional-requirements" aria-label="Permalink to &quot;4. Các ràng buộc phi chức năng quan trọng (Key Non-Functional Requirements)&quot;">​</a></h2><ul><li><strong>Giao diện (UI/UX):</strong> Phải responsive (Desktop 1440px làm chuẩn; Mobile 375px đáp ứng các luồng cốt lõi: Xem Calendar, Phê duyệt bài viết, Check status). Hiển thị thông báo dạng Toast, có thanh Loading indicator khi AI đang xử lý nội dung.</li><li><strong>Hiệu năng (Performance):</strong> API chuẩn phản hồi &lt; 1s. AI tạo Text &lt; 10s, Tạo Ảnh &lt; 30s, Tạo Video &lt; 3 phút. Hàng đợi đăng bài phân phối trong vòng 30s so với lịch hẹn. Hỗ trợ tối thiểu 200 người dùng đồng thời.</li><li><strong>Bảo mật (Security):</strong> Token JWT ngắn hạn (15 phút) kết hợp Refresh Token (30 ngày) lưu trong HttpOnly cookie. Mật khẩu hash hoàn toàn. Mọi hành động phê duyệt, quản trị phải được ghi Log hệ thống (Audit Logs).</li><li><strong>Ngôn ngữ:</strong> Hỗ trợ đa ngôn ngữ Anh/Việt (Localization định dạng ngày giờ, tiền tệ VND/USD).</li></ul>',10)])])}const p=t(r,[["render",a]]);export{d as __pageData,p as default};
